const duckUrl='https://raw.githubusercontent.com/ezam0000/ezpz-rubber-duck/82f2bbb/src/assets/duck.glb';

/** Modified SCEA Duck mesh. See licenses/SCEA.txt and THIRD_PARTY.md. */
export function createDuck(color:string,onError:()=>void,onReady:()=>void){
 const root=new T.Group();let mesh:T.Mesh|null=null,disposed=false,compression=0;
 const textures=new Set<T.Texture>();
 new GLTFLoader().load(duckUrl,gltf=>{
  if(disposed){gltf.scene.traverse(o=>{if(o instanceof T.Mesh){o.geometry.dispose();const m=o.material as T.MeshStandardMaterial;m.map?.dispose();m.dispose()}});return}
  gltf.scene.updateMatrixWorld(true);
  let source:T.Mesh|undefined;
  gltf.scene.traverse(o=>{if(o instanceof T.Mesh)source=o});
  if(!source){onError();return}
  const geometry=source.geometry.clone().applyMatrix4(source.matrixWorld);
  // Source faces +X; interaction convention faces +Z. Center the broad flotation body.
  geometry.rotateY(-Math.PI/2);geometry.computeBoundingBox();
  const box=geometry.boundingBox!,height=box.max.y-box.min.y,scale=1.93/height;
  geometry.translate(-(box.min.x+box.max.x)/2,-box.min.y,-(box.min.z+box.max.z)/2);
  geometry.scale(scale,scale,scale);geometry.translate(0,.085,0);
  const original=source.material as T.MeshStandardMaterial;
  const map=original.map!;textures.add(map);map.anisotropy=4;
  const material=new T.MeshPhysicalMaterial({map,color:'white',roughness:.40,metalness:0,clearcoat:.04,clearcoatRoughness:.4});
  const bodyColor=new T.Color(color);
  material.onBeforeCompile=shader=>{
   shader.uniforms.bodyColor={value:bodyColor};
   shader.fragmentShader='uniform vec3 bodyColor;\n'+shader.fragmentShader;
   shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>',`#include <map_fragment>
    float yellowMask=smoothstep(.22,.48,diffuseColor.g)*smoothstep(.55,.8,diffuseColor.r)*(1.-smoothstep(.08,.22,diffuseColor.b));
    float moldShade=.78+.22*clamp(diffuseColor.g/.72,0.,1.);
    diffuseColor.rgb=mix(diffuseColor.rgb,bodyColor*moldShade,yellowMask);
   `);
  };
  const deformed=geometry.clone(),p=deformed.attributes.position,normals=deformed.attributes.normal;
  for(let i=0;i<p.count;i++){
   const x=p.getX(i),y=p.getY(i),z=p.getZ(i),belly=Math.exp(-(((y-.62)/.50)**2));
   p.setXYZ(i,x*(1+.15*belly),y-.28*T.MathUtils.smoothstep(y,.20,1.22),z*(1+.09*belly));
   const derivative=-2*(y-.62)/(.50*.50)*belly,t=T.MathUtils.clamp((y-.20)/1.02,0,1);
   const nx=normals.getX(i)/(1+.15*belly),nz=normals.getZ(i)/(1+.09*belly);
   const ny=(normals.getY(i)-x*.15*derivative*nx-z*.09*derivative*nz)/(1-.28*6*t*(1-t)/1.02);
   const length=Math.hypot(nx,ny,nz);normals.setXYZ(i,nx/length,ny/length,nz/length);
  }
  geometry.morphAttributes.position=[deformed.attributes.position.clone()];geometry.morphAttributes.normal=[deformed.attributes.normal.clone()];deformed.dispose();
  mesh=new T.Mesh(geometry,material);mesh.castShadow=true;mesh.morphTargetInfluences![0]=compression;root.add(mesh);onReady();
  source.geometry.dispose();original.dispose();
 },undefined,()=>{if(!disposed)onError()});
 return {root,deform(value:number){compression=value;if(mesh)mesh.morphTargetInfluences![0]=value},dispose(){disposed=true;textures.forEach(t=>t.dispose())}};
}


// Physical surface normals are derived from propagating, damped circular wave packets.
export function createWater(){
 const uniforms={tDiffuse:{value:null},color:{value:new T.Color()},textureMatrix:{value:new T.Matrix4()},time:{value:0},origin:{value:new T.Vector2()},events:{value:Array.from({length:8},()=>new T.Vector4(0,0,-100,0))},baseColor:{value:new T.Color('#a9d7d8')}};
 const shader={uniforms,vertexShader:`
 uniform mat4 textureMatrix;varying vec4 vUv;varying vec2 surface;void main(){vUv=textureMatrix*vec4(position,1.);vec4 w=modelMatrix*vec4(position,1.);surface=w.xz;gl_Position=projectionMatrix*viewMatrix*w;}
 `,fragmentShader:`
 precision highp float;uniform sampler2D tDiffuse;varying vec4 vUv;varying vec2 surface;uniform float time;uniform vec2 origin;uniform vec4 events[8];uniform vec3 baseColor;
 float heightAt(vec2 p){
  float h=.004*sin(p.x*2.6+p.y*1.7+time*.65)+.003*sin(p.y*3.8-p.x*1.2-time*.43);
  for(int i=0;i<8;i++){
   vec4 e=events[i];float age=time-e.z;float d=length(p-e.xy);float r=d-age*1.65;
   float wave=sin(r*13.)*exp(-r*r*1.8)*exp(-age*.65)*e.w;
   if(age>0.&&age<7.)h+=wave;
  }
  return h;
 }
 void main(){
  float eps=.025;float h=heightAt(surface);
  vec3 n=normalize(vec3(-(heightAt(surface+vec2(eps,0.))-h)/eps,1.,-(heightAt(surface+vec2(0.,eps))-h)/eps));
  vec3 light=normalize(vec3(-.4,.9,.35));
  float diffuse=dot(n,light);float spec=pow(max(dot(n,normalize(vec3(-.12,1.,.14))),0.),180.);
  vec2 q=(surface-origin)/vec2(.90,1.0);float contact=exp(-dot(q,q)*1.7);
  vec3 color=baseColor*(.94+(diffuse-.87)*.35-contact*.25)+vec3(.78,.95,.92)*spec*.22;
  vec2 uv=vUv.xy/vUv.w+n.xz*.012;
  vec3 reflection=texture2D(tDiffuse,uv).rgb*.28;
  reflection+=(texture2D(tDiffuse,uv+vec2(.003,0.)).rgb+texture2D(tDiffuse,uv-vec2(.003,0.)).rgb+texture2D(tDiffuse,uv+vec2(0.,.003)).rgb+texture2D(tDiffuse,uv-vec2(0.,.003)).rgb)*.18;
  color=mix(color,reflection,.22);
  gl_FragColor=vec4(color,1.);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
 }
 `};
 const mesh=new Reflector(new T.PlaneGeometry(2000,2000),{shader,textureWidth:768,textureHeight:768,multisample:0,clipBias:.003});
 const material=mesh.material as T.ShaderMaterial;material.toneMapped=false;const live=material.uniforms;mesh.rotation.x=-Math.PI/2;mesh.position.y=.28;
 let index=0;
 return {mesh,dispose(){mesh.getRenderTarget().dispose()},update(time:number,x:number,z:number){live.time.value=time;live.origin.value.set(x,z)},ripple(x:number,z:number,time:number,strength=.035){live.events.value[index%8].set(x,z,time,strength);index++}};
}


export interface RubberDuckProps{color?:string;sound?:boolean;className?:string;initialYaw?:number}
/** Standalone direct-manipulation toy. No visible controls or typography. */
